function teachCourseBlock(host,row){if(!host||!row)return;let block=host.querySelector('.teach-course-reason');if(!block){block=document.createElement('div');block.className='teach-course-reason';const heading=host.querySelector('h4,h3');if(heading)heading.after(block);else host.prepend(block);}const html=`<p><b>为什么：</b>${esc(row[0])}</p><p><b>完成后看：</b>${esc(row[1])}</p>`;if(block.innerHTML!==html)block.innerHTML=html;}
const teachPointerBase=tutorialPointerList;tutorialPointerList=function(host,ops){const index=teachPointerBase(host,ops);if(host===tutorialCoach)teachCourseBlock(host.querySelector('.tm-body'),CourseTeaching.media[tutorialSession()?.step||0]);return index;};
const teachDtPaintBase=dtPaint;dtPaint=function(){teachDtPaintBase();if(dtActive())teachCourseBlock(dtCoach.querySelector('.dt-body'),CourseTeaching.source[dtSession().step]);};
const teachRttPaintBase=rttPaint;rttPaint=function(){teachRttPaintBase();if(rttActive())teachCourseBlock(rttCoach.querySelector('.rtt-body'),CourseTeaching.runtime[rttSession().step]);};
const teachGuideBase=renderGuide;renderGuide=function(){teachGuideBase();if(aidActive()){const parent=$('#guide .aid-course');teachCourseBlock(parent,['自然语言开发也必须先读源码、再做最小修改、实际测试并核对结果。','逐步记录出现真实正文、差异、测试退出码和预览；回滚后重新读取原文。']);}};
const teachHomeBase=tutorialHomeMarkup;tutorialHomeMarkup=function(v){let html=teachHomeBase(v);html=html.replace('在独立练习板里搭项目、配成员、发任务、连线和复盘，原画板不受影响。','在真实操作中理解每一步：为什么做、怎么做、做完看哪里，再换成自己的任务独立试用。').replace('本地演练 · 无需 API · 不真实发布','API 实操使用已配置模型额度；免费课程单独标明。').replace(/<ol class="tm-steps">([\s\S]*?)<\/ol>/,'<details class="teach-media-outline"><summary>自媒体协作免费课 · 学习内容</summary><ol class="tm-steps">$1</ol></details>');const match=html.match(/<section class="feature-entry"><p class="learning-intro">[\s\S]*?<\/section>/);if(match){const t=featureSession(),answers=t?.assessments||{},understood=Object.entries(answers).filter(([step,a])=>TeachingCore.lessons[+step]?.answer===a).length;const intro=match[0].replace('亮点工具实操','边用边学 · 核心能力').replace('</section>',`<p class="teach-learning-progress">操作进度：${t?(t.status==='complete'?8:t.step+1):0}/8课 · 理解检查：${understood}/8个概念</p><p class="teach-transfer">学会：让 AI 操作软件、选择方法、推敲请求、看懂授权。做完后，在自己的项目里再试一次。</p><button data-learn="offline">仅体验固定本地示范</button></section>`);html=html.replace(match[0],'').replace(/<button data-learn="offline">仅体验固定本地示范<\/button>/g,'').replace(/(<p class="tm-safe">[\s\S]*?<\/p>)/,'$1'+intro);}return html;};

